<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>مواعيد العيادة</title>
<style>
  body { font-family: Arial, sans-serif; direction: rtl; margin: 0; padding: 0; background-color: #f5f5f5; }
  .container { max-width: 480px; margin: 0 auto; padding: 16px; background-color: #fff; height: 100vh; box-sizing: border-box; }
  .month-nav { display: flex; align-items: center; justify-content: center; gap: 16px; margin-bottom: 16px; }
  .nav-btn { background: none; border: none; font-size: 24px; cursor: pointer; }
  .month-name { font-size: 20px; font-weight: bold; }
  .calendar { width: 100%; border-collapse: collapse; margin-bottom: 16px; }
  .calendar th, .calendar td { text-align: center; padding: 8px; border: 1px solid #ddd; }
  .calendar th { background-color: #e0e0e0; }
  .calendar td { cursor: pointer; }
  .calendar td.empty { border: none; }
  .calendar td.today { background-color: #ffeb3b; }
  .calendar td.selected { background-color: #007bff; color: white; }
  .time-slots { display: flex; overflow-x: auto; gap: 8px; margin-bottom: 16px; padding: 4px 0; }
  .time-slot { padding: 8px 12px; border: 1px solid #ccc; border-radius: 4px; cursor: pointer; white-space: nowrap; }
  .time-slot.selected { background-color: #007bff; color: white; }
  .doctor { margin-bottom: 16px; font-size: 18px; text-align: center; }
  .confirm-btn { width: 100%; padding: 12px; background-color: #28a745; color: white; border: none; border-radius: 4px; font-size: 16px; cursor: pointer; }
  .confirm-btn:disabled { background-color: #6c757d; cursor: not-allowed; }
</style>
</head>
<body>
<div class="container">
  <div class="month-nav">
    <button class="nav-btn" id="prev-month">◀</button>
    <span class="month-name" id="month-name"></span>
    <button class="nav-btn" id="next-month">▶</button>
  </div>
  <table class="calendar" id="calendar">
    <thead id="calendar-head"></thead>
    <tbody id="calendar-body"></tbody>
  </table>
  <div class="time-slots" id="time-slots"></div>
  <div class="doctor">د. محمد علي</div>
  <button class="confirm-btn" id="confirm-btn" disabled>تأكيد الحجز</button>
</div>

<script>
  const monthNames = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"];
  const dayNames = ["السبت", "الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة"];
  const timeSlots = ["9:00", "9:30", "10:00", "10:30", "11:00", "11:30", "12:00"];

  let currentDate = new Date();
  let selectedDate = null;
  let selectedTime = null;

  const calendarHead = document.getElementById('calendar-head');
  const calendarBody = document.getElementById('calendar-body');
  const monthNameEl = document.getElementById('month-name');
  const timeSlotsEl = document.getElementById('time-slots');
  const confirmBtn = document.getElementById('confirm-btn');

  function renderCalendar() {
    calendarHead.innerHTML = '';
    calendarBody.innerHTML = '';

    monthNameEl.textContent = `${monthNames[currentDate.getMonth()]} ${currentDate.getFullYear()}`;

    const headRow = document.createElement('tr');
    dayNames.forEach(day => {
      const th = document.createElement('th');
      th.textContent = day;
      headRow.appendChild(th);
    });
    calendarHead.appendChild(headRow);

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDay = new Date(year, month, 1);
    const startDay = (firstDay.getDay() + 1) % 7; // Saturday = 0
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    let row = document.createElement('tr');
    for (let i = 0; i < startDay; i++) {
      const td = document.createElement('td');
      td.classList.add('empty');
      row.appendChild(td);
    }

    const today = new Date();
    for (let d = 1; d <= daysInMonth; d++) {
      const td = document.createElement('td');
      td.textContent = d;
      if (today.getFullYear() === year && today.getMonth() === month && today.getDate() === d) {
        td.classList.add('today');
      }
      if (selectedDate && selectedDate.getFullYear() === year && selectedDate.getMonth() === month && selectedDate.getDate() === d) {
        td.classList.add('selected');
      }
      td.addEventListener('click', () => selectDate(new Date(year, month, d)));
      row.appendChild(td);
      if ((startDay + d) % 7 === 0) {
        calendarBody.appendChild(row);
        row = document.createElement('tr');
      }
    }
    if (row.children.length > 0) {
      calendarBody.appendChild(row);
    }
  }

  function selectDate(date) {
    selectedDate = date;
    renderCalendar();
  }

  function renderTimeSlots() {
    timeSlotsEl.innerHTML = '';
    timeSlots.forEach(time => {
      const div = document.createElement('div');
      div.className = 'time-slot';
      div.textContent = time;
      if (selectedTime === time) {
        div.classList.add('selected');
      }
      div.addEventListener('click', () => {
        selectedTime = time;
        renderTimeSlots();
        updateConfirmBtn();
      });
      timeSlotsEl.appendChild(div);
    });
  }

  function updateConfirmBtn() {
    confirmBtn.disabled = !(selectedDate && selectedTime);
  }

  document.getElementById('prev-month').addEventListener('click', () => {
    currentDate.setMonth(currentDate.getMonth() - 1);
    renderCalendar();
  });
  document.getElementById('next-month').addEventListener('click', () => {
    currentDate.setMonth(currentDate.getMonth() + 1);
    renderCalendar();
  });

  confirmBtn.addEventListener('click', () => {
    if (selectedDate && selectedTime) {
      alert(`تم حجز موعد في ${selectedDate.toDateString()} الساعة ${selectedTime}`);
    }
  });

  renderCalendar();
  renderTimeSlots();
  updateConfirmBtn();
</script>
</body>
</html>
